      ]
    },
    {
      "id": "F7",
      "kind": "capability",
      "status": "assessed",
      "fact": "Opponents of placement under the Joint Chiefs of Staff feared it could weaken department-wide intelligence effectiveness, produce a loose confederation of organizations, and restrict the Director's access to Defense components and the national intelligence community.",
